function groupByFirstLetter(words) {
  const map = new Map();
  for (const w of words) {
    if (!w) continue;
    const letter = w[0].toLowerCase();
    if (!map.has(letter)) map.set(letter, []);
    map.get(letter).push(w);
  }
  return Array.from(map.entries());
}

